export function embedURL(link){const u=new URL(link),h=u.hostname.replace(/^www\./,'');if(h==='youtu.be'||h==='youtube.com'||h==='m.youtube.com'){const id=h==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').filter(Boolean)[1];if(/^[\w-]{11}$/.test(id||''))return'https://www.youtube-nocookie.com/embed/'+id;}if(h==='instagram.com'){const m=u.pathname.match(/^\/(reel|p|tv)\/([\w-]+)/);if(m)return'https://www.instagram.com/'+m[1]+'/'+m[2]+'/embed/';}if(h==='tiktok.com'){const m=u.pathname.match(/\/video\/(\d+)/);if(m)return'https://www.tiktok.com/player/v1/'+m[1];}if(h==='facebook.com'||h==='m.facebook.com')return'https://www.facebook.com/plugins/video.php?href='+encodeURIComponent(link)+'&show_text=false';return null;}
export function addEmbeddedVideo(list,url,node){const src=embedURL(url);if(!src)return;const frame=node('iframe','social-video-frame');frame.src=src;frame.title='Video del vehículo';frame.loading='lazy';frame.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';frame.style.cssText='width:100%;height:340px;border:0;border-radius:12px;background:#101722';list.append(frame);}
